#!/bin/bash
#
# Деплой стека blog. Файл написан deploycli: правка руками живёт до следующего
# прогона генератора.
#
# Запуск:
#   deploy/deploy.sh <контур> <SHA>
#
# Контур и полный SHA коммита приходят параметрами запуска (ADR-006): имя
# контура едет в запись деплоя и в журнал, SHA называет каталог релиза. Скрипт
# не читает ни одной переменной раннера форжи — ручной запуск на хосте обязан
# давать тот же результат, что запуск через форжу (ADR-007).
#
# Образы тянет отдельное подключение, идущее до этого скрипта: у одного вызова
# ssh один stdin, и здесь он занят содержимым файла окружения, а логин в реестр,
# резолв digest и pull едут своим (ADR-005, ADR-012). Поэтому ни docker login,
# ни docker pull, ни docker logout в этом файле не встречаются.
#
# Замок охватывает весь скрипт, а не шаг миграции (ADR-008): ручной запуск и
# запуск через форжу не должны совпасть двумя миграциями, а Alembic и Django
# сами себя не блокируют. Занятый замок — отказ без ожидания, с именем держателя
# и временем взятия: ошибочный отказ стоит одной повторной команды, а деплой,
# приехавший в середину чужого, — неизвестного состояния (ADR-009).
#
# deploy/rollback.sh берёт тот же замок; вызванный отсюда, он видит путь взятого
# замка в DEPLOYCLI_LOCK_HELD и повторно его не берёт.
#
# set -x в блоках, работающих с содержимым файла окружения, запрещён: отладочный
# вывод напечатал бы значения (ADR-012).

set -euo pipefail

readonly STACK_DIR='/opt/blog'
readonly LOCK_FILE="${STACK_DIR}/.deploy.lock"

die() {
  printf 'деплой: %s\n' "$*" >&2
  exit 1
}

[ "$#" -eq 2 ] || die "запуск: deploy/deploy.sh <контур> <SHA>"

readonly CONTOUR="$1"
readonly COMMIT_SHA="$2"

[ -n "${CONTOUR}" ] || die "имя контура пустое: назовите контур из файла ответов"

# SHA называет каталог релиза, поэтому проверяется грамматикой, а не на
# непустоту: короткий SHA или имя ветки указали бы на каталог, которого нет ни у
# одной записи деплоя.
[[ "${COMMIT_SHA}" =~ ^[0-9a-f]{40}$ ]] \
  || die "SHA '${COMMIT_SHA}' не полный: нужны 40 знаков [0-9a-f]"

readonly RELEASE_DIR="${STACK_DIR}/releases/${COMMIT_SHA}"

# Compose зовётся только через эту обёртку. --project-directory каталога стека
# обязателен: проектным каталогом по умолчанию стал бы каталог первого файла -f,
# то есть каталог релиза, и относительный .env искался бы там (ADR-012).
compose() {
  docker compose \
    --project-directory "${STACK_DIR}" \
    -f "${RELEASE_DIR}/docker-compose.yml" \
    -f "${RELEASE_DIR}/docker-compose.prod.yml" \
    "$@"
}

# --- Замок ---
# Берётся до первого шага и держится до конца скрипта: под ним и предполёт, и
# запуск новой версии (ADR-008). Отпускается закрытием дескриптора при выходе,
# любым.

[ -d "${STACK_DIR}" ] || die "каталога стека ${STACK_DIR} нет: хост не подготовлен"

command -v flock >/dev/null 2>&1 \
  || die "flock на хосте не найден: без него ручной запуск и запуск через форжу сошлись бы двумя деплоями"

# Открытие на чтение и запись: открытие только на запись усекло бы файл, и
# отказавший запуск прочитал бы пустую строку вместо имени держателя.
exec 9<>"${LOCK_FILE}"

if ! flock -n 9; then
  holder=''
  read -r holder <"${LOCK_FILE}" || true
  [ -n "${holder}" ] || holder='ещё не назвался, замок взят только что'
  die "замок ${LOCK_FILE} занят, ждать не буду; держатель — ${holder}"
fi

# Держатель называет себя сразу после взятия: отказавший запуск печатает эту
# строку дословно.
printf "pid %s, контур '%s', SHA %s, взят %s\n" \
  "$$" "${CONTOUR}" "${COMMIT_SHA}" "$(date -u '+%Y-%m-%dT%H:%M:%SZ')" \
  >"${LOCK_FILE}"

# deploy/rollback.sh, вызванный отсюда, видит этот путь и повторно замок не
# берёт (ADR-009).
export DEPLOYCLI_LOCK_HELD="${LOCK_FILE}"

